package agent

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/exec"
	"regexp"
	"strings"
	"sync"
	"time"
	"unicode/utf8"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// TextCommandRunner matches exec.CommandContext and allows tests to inject a runner.
type TextCommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd

// RunIsolatedTextGeneratorCLI executes a text-generation CLI in an isolated temp
// directory with all GIT_* environment variables removed. This avoids recursive
// hook triggers and repo side effects while preserving provider-specific flags.
func RunIsolatedTextGeneratorCLI(ctx context.Context, runner TextCommandRunner, binary, displayName string, args []string, stdin string) (string, error) {
	if runner == nil {
		runner = exec.CommandContext
	}

	cmd := runner(ctx, binary, args...)
	cmd.Dir = os.TempDir()
	cmd.Env = StripGitEnv(os.Environ())
	if stdin != "" {
		cmd.Stdin = strings.NewReader(stdin)
	}

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", context.DeadlineExceeded
		}
		if errors.Is(ctx.Err(), context.Canceled) {
			return "", context.Canceled
		}
		var execErr *exec.Error
		if errors.As(err, &execErr) {
			return "", fmt.Errorf("%s CLI not found: %w", displayName, err)
		}
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			detail := strings.TrimSpace(stderr.String())
			if detail == "" {
				detail = strings.TrimSpace(stdout.String())
			}
			if detail == "" {
				detail = err.Error()
			}
			return "", fmt.Errorf("%s CLI failed (exit %d): %s: %w", displayName, exitErr.ExitCode(), detail, err)
		}
		return "", fmt.Errorf("failed to run %s CLI: %w", displayName, err)
	}

	result := strings.TrimSpace(stdout.String())
	if result == "" {
		return "", fmt.Errorf("%s CLI returned empty output", displayName)
	}
	return result, nil
}

// summaryProviderBinaries maps agent names to the CLI binary that
// RunIsolatedTextGeneratorCLI will exec. Used by IsSummaryCLIAvailable to
// check PATH instead of repo-level DetectPresence, because a repo can use
// one agent for development while a different agent generates summaries.
var summaryProviderBinaries = map[types.AgentName]string{
	AgentNameClaudeCode: "claude",
	AgentNameCodex:      "codex",
	AgentNameCopilotCLI: "copilot",
	AgentNameCursor:     "agent",
	AgentNameGemini:     "gemini",
}

// IsSummaryCLIAvailable reports whether the CLI binary for a summary-capable
// agent is on PATH. This is distinct from DetectPresence, which checks
// repo-level agent configuration — a repo configured with Claude Code for
// development can still use Codex or Gemini for summary generation as long
// as the binary is installed.
func IsSummaryCLIAvailable(name types.AgentName) bool {
	binary, ok := summaryProviderBinaries[name]
	if !ok {
		return false
	}
	_, err := exec.LookPath(binary)
	return err == nil
}

func StripGitEnv(env []string) []string {
	filtered := make([]string, 0, len(env))
	for _, e := range env {
		if !strings.HasPrefix(e, "GIT_") {
			filtered = append(filtered, e)
		}
	}
	return filtered
}

// defaultStreamMaxLineBytes is the stdout scanner buffer size used when
// StreamConfig.MaxLineBytes is zero. 1 MiB comfortably fits the largest
// observed stream-json envelope lines without deadlocking on oversized ones.
const defaultStreamMaxLineBytes = 1 << 20

// StreamConfig configures a call to RunStreamingCLI. It captures the subprocess
// invocation plus the provider-specific fallback hooks so the runner can recover
// from older CLIs that reject streaming flags.
type StreamConfig struct {
	// Runner constructs the subprocess command. nil defaults to exec.CommandContext.
	Runner TextCommandRunner
	// Binary is the CLI binary name (passed to Runner).
	Binary string
	// DisplayName is the human-facing label used in error messages.
	DisplayName string
	// ProviderLabel is stamped onto every GenerationProgress emitted to progress.
	ProviderLabel string
	// Args are the CLI arguments (excluding the binary).
	Args []string
	// Stdin is piped to the subprocess. Empty means no stdin.
	Stdin string
	// LegacyFallback is invoked when the CLI rejects streaming flags (see
	// FallbackDetect). The returned text is returned as-is with no progress events.
	LegacyFallback func(ctx context.Context) (string, error)
	// FallbackDetect reports whether stderr indicates the CLI rejected the
	// streaming flags. When true and the subprocess failed, LegacyFallback runs.
	FallbackDetect func(stderr string) bool
	// MaxLineBytes sizes the stdout scanner buffer. 0 uses 1 MiB.
	MaxLineBytes int
}

// StreamState carries handler-owned scratch state across line invocations. The
// runner initializes StartedAt; handlers own everything else.
type StreamState struct {
	StartedAt            time.Time
	OutputTokensEstimate int
	Custom               map[string]any
}

// StreamResult is the terminal outcome returned by a StreamLineHandler. Exactly
// one of Text or Err is populated; Text triggers a synthetic PhaseDone emission
// while Err returns as-is and outranks context cancellation.
type StreamResult struct {
	Text         string
	DurationMs   int
	OutputTokens int
	Err          error
}

// StreamLineHandler processes one scanner line. It returns any progress events
// to forward, a non-nil *StreamResult to terminate the stream, and/or an error
// to abort immediately. Handlers must not block.
type StreamLineHandler func(line []byte, state *StreamState) (events []GenerationProgress, done *StreamResult, err error)

// RunStreamingCLI executes a streaming text-generation CLI, dispatching scanner
// lines to the supplied handler and forwarding progress events (stamped with
// cfg.ProviderLabel) to the progress callback. It owns the subprocess lifecycle
// including stdout drain + Wait and the terminal-branch decision table.
//
// The terminal branches run in strict priority order:
//  1. done.Err != nil                         → return done.Err (beats ctx cancel)
//  2. done.Text != ""                         → emit synthetic PhaseDone + return Text
//  3. ctx.Err() == context.DeadlineExceeded   → pass through sentinel
//  4. ctx.Err() == context.Canceled           → pass through sentinel
//  5. no terminal + Wait ok                   → "<Display>: stream exited without result"
//  6. Wait failed + FallbackDetect(stderr)    → cfg.LegacyFallback(ctx)
//  7. Wait failed otherwise                   → "<Display>: <stderr>: %w"
func RunStreamingCLI(
	ctx context.Context,
	cfg StreamConfig,
	handler StreamLineHandler,
	progress ProgressFn,
) (string, error) {
	runner := cfg.Runner
	if runner == nil {
		runner = exec.CommandContext
	}

	cmd := runner(ctx, cfg.Binary, cfg.Args...)
	cmd.Dir = os.TempDir()
	cmd.Env = StripGitEnv(os.Environ())
	if cfg.Stdin != "" {
		cmd.Stdin = strings.NewReader(cfg.Stdin)
	}

	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("%s: stdout pipe: %w", cfg.DisplayName, err)
	}
	var stderr bytes.Buffer
	cmd.Stderr = &stderr

	if err := cmd.Start(); err != nil {
		return "", fmt.Errorf("%s: start: %w", cfg.DisplayName, err)
	}

	// closeStdout drains any unread stdout then calls cmd.Wait exactly once. It is
	// invoked from every exit path so the subprocess cannot deadlock on a full
	// pipe. Guarded by sync.Once since Wait is not safe to call twice
	// (exec.ErrWaitAlreadyCalled).
	var (
		waitOnce sync.Once
		waitErr  error
	)
	closeStdout := func() {
		waitOnce.Do(func() {
			if _, drainErr := io.Copy(io.Discard, stdout); drainErr != nil {
				logging.Debug(ctx, "draining streaming stdout",
					slog.String("display", cfg.DisplayName),
					slog.String("error", drainErr.Error()))
			}
			waitErr = cmd.Wait()
		})
	}

	state := &StreamState{StartedAt: time.Now()}
	maxLine := cfg.MaxLineBytes
	if maxLine <= 0 {
		maxLine = defaultStreamMaxLineBytes
	}

	scanner := bufio.NewScanner(stdout)
	scanner.Buffer(make([]byte, 0, 64*1024), maxLine)

	emit := func(events []GenerationProgress) {
		if progress == nil {
			return
		}
		for _, ev := range events {
			ev.ProviderLabel = cfg.ProviderLabel
			progress(ev)
		}
	}

	var (
		done        *StreamResult
		handlerErr  error
		loopAborted bool
	)
	for scanner.Scan() {
		events, terminal, err := handler(scanner.Bytes(), state)
		emit(events)
		if err != nil {
			handlerErr = err
			loopAborted = true
			break
		}
		if terminal != nil {
			done = terminal
			loopAborted = true
			break
		}
	}
	scanErr := scanner.Err()
	if !loopAborted && scanErr != nil {
		handlerErr = scanErr
	}

	closeStdout()

	// Branch 1: handler-reported error beats ctx cancel.
	if done != nil && done.Err != nil {
		return "", done.Err
	}
	// Handler returned a non-StreamResult error (e.g. scanner failure).
	if handlerErr != nil {
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", context.DeadlineExceeded
		}
		if errors.Is(ctx.Err(), context.Canceled) {
			return "", context.Canceled
		}
		return "", fmt.Errorf("%s: %w", cfg.DisplayName, handlerErr)
	}
	// Branch 2: terminal text envelope → synthesize PhaseDone.
	if done != nil && done.Text != "" {
		durationMs := done.DurationMs
		if durationMs == 0 {
			durationMs = int(time.Since(state.StartedAt) / time.Millisecond)
		}
		if progress != nil {
			progress(GenerationProgress{
				Phase:         PhaseDone,
				OutputTokens:  done.OutputTokens,
				DurationMs:    durationMs,
				ProviderLabel: cfg.ProviderLabel,
			})
		}
		return done.Text, nil
	}
	// Branches 3 & 4: context cancellation sentinels.
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return "", context.DeadlineExceeded
	}
	if errors.Is(ctx.Err(), context.Canceled) {
		return "", context.Canceled
	}
	// Branch 5: clean exit without a terminal event.
	if waitErr == nil {
		return "", fmt.Errorf("%s: stream exited without result", cfg.DisplayName)
	}
	// Branch 6: CLI rejected streaming flags → legacy fallback.
	if cfg.FallbackDetect != nil && cfg.LegacyFallback != nil && cfg.FallbackDetect(stderr.String()) {
		return cfg.LegacyFallback(ctx)
	}
	// Branch 7: generic subprocess failure.
	detail := strings.TrimSpace(stderr.String())
	if detail == "" {
		return "", fmt.Errorf("%s: %w", cfg.DisplayName, waitErr)
	}
	return "", fmt.Errorf("%s: %s: %w", cfg.DisplayName, detail, waitErr)
}

// heartbeatStderrBufferBytes caps the stderr we retain for error reporting when
// a heartbeat subprocess fails. 10 KiB is enough for typical CLI banners and
// error traces without letting a chatty CLI balloon memory on a hang.
const heartbeatStderrBufferBytes = 10 * 1024

// heartbeatMaxLineRunes is the rune threshold above which forwarded stderr
// lines are truncated to heartbeatTruncateRunes + ellipsis. Rune-based to stay
// safe on multi-byte locales.
const heartbeatMaxLineRunes = 200

// heartbeatTruncateRunes is the rune count retained when a forwarded stderr
// line is truncated. Paired with a trailing "..." marker.
const heartbeatTruncateRunes = 100

// heartbeatPromptPrefixRunes is the rune-count prefix of stdin compared against
// stderr lines to suppress prompt-echo leakage from chatty CLIs.
const heartbeatPromptPrefixRunes = 40

// csiEscapeRegexp matches ECMA-48 CSI control sequences (e.g. color codes,
// cursor positioning, "\x1b[2K" erase-in-line). Applied to stderr before
// TrimSpace so ANSI-decorated banners collapse to their plain-text payload.
var csiEscapeRegexp = regexp.MustCompile(`\x1b\[[0-?]*[ -/]*[@-~]`)

// heartbeatNoisePrefixRegexp matches common CLI banner/noise prefixes that
// should be suppressed from heartbeat output. Case-insensitive; anchored at the
// start of the already-trimmed line.
var heartbeatNoisePrefixRegexp = regexp.MustCompile(`(?i)^(version |deprecation notice|warning: tls)`)

// defaultHeartbeatNoiseFilter applies the shared stderr hygiene rules: strip
// CSI escapes + carriage returns, TrimSpace, drop empty or known-noise lines,
// and truncate overlong lines. Returns the cleaned line and a kept flag.
func defaultHeartbeatNoiseFilter(line string) (string, bool) {
	cleaned := csiEscapeRegexp.ReplaceAllString(line, "")
	cleaned = strings.ReplaceAll(cleaned, "\r", "")
	cleaned = strings.TrimSpace(cleaned)
	if cleaned == "" {
		return "", false
	}
	if heartbeatNoisePrefixRegexp.MatchString(cleaned) {
		return "", false
	}
	if utf8.RuneCountInString(cleaned) > heartbeatMaxLineRunes {
		cleaned = runePrefix(cleaned, heartbeatTruncateRunes) + "..."
	}
	return cleaned, true
}

// runePrefix returns the first n runes of s. Unlike slicing s[:n] it is safe on
// multi-byte sequences.
func runePrefix(s string, n int) string {
	if n <= 0 {
		return ""
	}
	runes := []rune(s)
	if len(runes) <= n {
		return s
	}
	return string(runes[:n])
}

// HeartbeatConfig configures a RunWithHeartbeat invocation. Heartbeat mode is
// used for CLIs that cannot emit structured deltas; forwarded stderr lines
// surface as PhaseMessage events so the UI can show the call is alive.
type HeartbeatConfig struct {
	// ProviderLabel is stamped on every emitted GenerationProgress.
	ProviderLabel string
	// StderrFilter is an optional provider-specific filter applied AFTER the
	// default noise filter. Return true to keep the line; false to drop it.
	StderrFilter func(line string) bool
}

// RunWithHeartbeat runs a blocking CLI, emitting PhaseConnecting at start and
// PhaseDone on success. Stderr lines are tailed line-by-line, passed through a
// noise filter (+ optional caller filter), and forwarded as PhaseMessage
// events. On non-zero exit the buffered stderr is included in the returned
// error and no PhaseDone is emitted.
func RunWithHeartbeat(
	ctx context.Context,
	cfg HeartbeatConfig,
	binary string,
	args []string,
	stdin string,
	progress ProgressFn,
	runner TextCommandRunner,
) (string, error) {
	if runner == nil {
		runner = exec.CommandContext
	}

	emit := func(ev GenerationProgress) {
		if progress == nil {
			return
		}
		ev.ProviderLabel = cfg.ProviderLabel
		progress(ev)
	}

	emit(GenerationProgress{Phase: PhaseConnecting})

	cmd := runner(ctx, binary, args...)
	cmd.Dir = os.TempDir()
	cmd.Env = StripGitEnv(os.Environ())
	if stdin != "" {
		cmd.Stdin = strings.NewReader(stdin)
	}

	var stdout bytes.Buffer
	cmd.Stdout = &stdout

	stderrPipe, err := cmd.StderrPipe()
	if err != nil {
		return "", fmt.Errorf("heartbeat: stderr pipe: %w", err)
	}

	started := time.Now()
	if err := cmd.Start(); err != nil {
		return "", fmt.Errorf("heartbeat: start: %w", err)
	}

	// Rune-based prefix of stdin used to suppress prompt echo.
	promptPrefix := runePrefix(stdin, heartbeatPromptPrefixRunes)

	var stderrBuf bytes.Buffer
	scanner := bufio.NewScanner(stderrPipe)
	scanner.Buffer(make([]byte, 0, 64*1024), defaultStreamMaxLineBytes)

	scanDone := make(chan struct{})
	go func() {
		defer close(scanDone)
		for scanner.Scan() {
			raw := scanner.Text()
			// Retain raw bytes (capped) for error reporting on non-zero exit.
			if stderrBuf.Len() < heartbeatStderrBufferBytes {
				remaining := heartbeatStderrBufferBytes - stderrBuf.Len()
				if len(raw)+1 <= remaining {
